import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const GuiYeuCauBaoTri = () => {
    const now = new Date();
    const [selectedDate, setSelectedDate] = useState(now.getDate());
    const [selectedMonth, setSelectedMonth] = useState(now.getMonth() + 1);
    const [selectedYear, setSelectedYear] = useState(now.getFullYear());

    const [userRoom, setUserRoom] = useState('');
    const [title, setTitle] = useState('');
    const [description, setDescription] = useState('');
    const [dailyRequests, setDailyRequests] = useState([]);

    useEffect(() => {
        const profile = JSON.parse(localStorage.getItem('userProfile') || '{}');
        setUserRoom(profile.room_id || profile.room || '102');
        fetchData();
    }, [selectedDate, selectedMonth, selectedYear]);

    const fetchData = () => {
        const allData = JSON.parse(localStorage.getItem('maintenance_db') || '[]');
        const filtered = allData.filter(item => 
            item.day === selectedDate && 
            item.month === selectedMonth && 
            item.year === selectedYear
        );
        setDailyRequests(filtered);
    };

    const handleSendRequest = () => {
        if (!title.trim() || !description.trim()) return alert("Vui lòng điền đủ thông tin!");

        const newRequest = {
            id: Date.now(),
            room: userRoom,
            title: title,
            issue: description,
            status: 'pending',
            day: selectedDate,
            month: selectedMonth,
            year: selectedYear,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        };

        const allData = JSON.parse(localStorage.getItem('maintenance_db') || '[]');
        localStorage.setItem('maintenance_db', JSON.stringify([newRequest, ...allData]));

        setTitle('');
        setDescription('');
        fetchData();
        alert("Gửi yêu cầu thành công!");
    };

    const getStatusText = (status) => {
        if (status === 'pending') return '⏳ Chờ xử lý';
        if (status === 'processing') return '🛠 Đang sửa';
        return '✅ Hoàn thành';
    };

    return (
        <div style={containerStyle}>
            <div style={headerStyle}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '20px' }}>🛠 GỬI YÊU CẦU BẢO TRÌ</h2>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select value={selectedDate} onChange={(e) => setSelectedDate(Number(e.target.value))} style={selectSmall}>
                        {Array.from({length:31},(_,i)=><option key={i+1} value={i+1}>Ngày {i+1}</option>)}
                    </select>
                    <select value={selectedMonth} onChange={(e) => setSelectedMonth(Number(e.target.value))} style={selectSmall}>
                        {Array.from({length:12},(_,i)=><option key={i+1} value={i+1}>Tháng {i+1}</option>)}
                    </select>
                </div>
            </div>

            <div style={mainLayout}>
                <div style={formCardGlass}>
                    <h3 style={{ color: '#8b5e5e', marginTop: 0, fontSize: '18px' }}>Yêu cầu từ phòng {userRoom}</h3>
                    <div style={inputGroup}>
                        <label style={labelStyle}>Tiêu đề sự cố:</label>
                        <input style={inputStyle} value={title} onChange={(e) => setTitle(e.target.value)} placeholder="VD: Hỏng bóng đèn..." />
                    </div>

                    <div style={inputGroup}>
                        <label style={labelStyle}>Mô tả chi tiết:</label>
                        <textarea style={areaStyle} value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Mô tả cụ thể..." />
                    </div>

                    <button onClick={handleSendRequest} style={btnStyle}>XÁC NHẬN GỬI</button>
                </div>

                <div style={listCardGlass}>
                    <h3 style={{ color: '#8b5e5e', marginTop: 0, fontSize: '18px' }}>Yêu cầu cư dân ngày {selectedDate}/{selectedMonth}</h3>
                    <div style={{ overflowY: 'auto', flex: 1, paddingRight: '10px' }} className="custom-scrollbar">
                        {dailyRequests.length > 0 ? dailyRequests.map(req => (
                            <div key={req.id} style={itemStyle}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                    <strong style={{fontSize: '15px', color: '#333'}}>P.{req.room}: {req.title}</strong>
                                    <span style={badgeStyle(req.status)}>{getStatusText(req.status)}</span>
                                </div>
                                <p style={{ fontSize: '13px', color: '#555', margin: '8px 0' }}>{req.issue}</p>
                                <div style={{ fontSize: '11px', color: '#999', textAlign: 'right' }}>{req.time}</div>
                            </div>
                        )) : (
                            <div style={emptyStyle}>🍃 Chưa có báo cáo nào.</div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

// --- STYLES CƯ DÂN ---
const containerStyle = { flex: 1, display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', backgroundPosition: 'center', borderRadius: '30px', height: 'calc(100vh - 120px)', overflow: 'hidden' };
const headerStyle = { padding: '20px 30px', background: 'rgba(0,0,0,0.4)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', backdropFilter: 'blur(10px)' };
const mainLayout = { flex: 1, display: 'flex', gap: '20px', padding: '20px', minHeight: 0 };
const formCardGlass = { width: '320px', background: 'rgba(255, 255, 255, 0.8)', backdropFilter: 'blur(15px)', borderRadius: '25px', padding: '25px', display: 'flex', flexDirection: 'column', boxShadow: '0 8px 32px rgba(0,0,0,0.2)', border: '1px solid rgba(255,255,255,0.3)' };
const listCardGlass = { flex: 1, background: 'rgba(255, 255, 255, 0.6)', backdropFilter: 'blur(15px)', borderRadius: '25px', padding: '25px', display: 'flex', flexDirection: 'column', border: '1px solid rgba(255,255,255,0.2)' };
const inputGroup = { marginBottom: '15px' };
const labelStyle = { display: 'block', fontSize: '12px', fontWeight: 'bold', color: '#8b5e5e', marginBottom: '5px' };
const inputStyle = { width: '100%', padding: '12px', borderRadius: '12px', border: '1px solid rgba(0,0,0,0.1)', fontSize: '14px', outline: 'none', boxSizing: 'border-box' };
const areaStyle = { ...inputStyle, height: '120px', resize: 'none' };
const btnStyle = { padding: '15px', borderRadius: '15px', border: 'none', backgroundColor: '#8b5e5e', color: '#fff', fontWeight: 'bold', cursor: 'pointer', transition: '0.3s' };
const selectSmall = { padding: '8px 12px', borderRadius: '10px', border: 'none', fontWeight: 'bold' };
const itemStyle = { padding: '15px', background: 'rgba(255, 255, 255, 0.9)', borderRadius: '15px', marginBottom: '12px', borderLeft: '5px solid #8b5e5e' };
const badgeStyle = (s) => ({ fontSize: '10px', padding: '4px 10px', borderRadius: '10px', fontWeight: 'bold', backgroundColor: s==='pending'?'#ffebeb':s==='processing'?'#fff9db':'#ebffef', color: s==='pending'?'#e03131':s==='processing'?'#f08c00':'#2f9e44' });
const emptyStyle = { textAlign: 'center', marginTop: '60px', color: '#777' };

export default GuiYeuCauBaoTri;
